// Ref: #/components/schemas/SandboxExec
type SandboxExec struct {
	// Command argv executed in the sandbox.
	Command   []string  `json:"command"`
	CreatedAt time.Time `json:"createdAt"`
	// Additional environment variables for the exec process.
	Env OptSandboxExecEnv `json:"env"`
	// Runtime error detail when the exec failed.
	Error OptString `json:"error"`
	// Process exit code when the exec has exited.
	ExitCode OptInt64    `json:"exitCode"`
	ExitedAt OptDateTime `json:"exitedAt"`
	// Harness this exec runs, when created in harness (terminal) mode.
	HarnessId OptString `json:"harnessId"`
	// Sandbox exec runtime ID.
	ID string `json:"id"`
	// Caller-supplied exec metadata.
	Metadata OptSandboxExecMetadata `json:"metadata"`
	// Sandbox-local process ID when known.
	Pid OptInt64 `json:"pid"`
	// Whether this is the sandbox's primary harness terminal.
	Primary   OptBool     `json:"primary"`
	StartedAt OptDateTime `json:"startedAt"`
	// Harness terminal mode only: the command typed into the shell (command
	// above) once it starts, as if the caller had typed it themselves. This is
	// what is actually running in the foreground, and what gives it real job
	// control (Ctrl-Z, fg, bg) — see command for what process is literally
	// executed.
	StartupCommand []string `json:"startupCommand"`
	// Current observed exec runtime status. installing is a terminal-layer
	// phase: the exec record exists and its hooks/files are still being
	// prepared, before the harness process is launched (starting -> running).
	Status SandboxExecStatus `json:"status"`
	// Whether this run ended because it was asked to stop rather than on its own. It cannot be inferred
	// after the fact - a stopped process and one killed by a signal it did not choose leave the same
	// record - so it is recorded when the stop is requested and cleared by the next run.
	Stopped OptBool `json:"stopped"`
	// Whether the exec process was started with a PTY.
	Tty bool `json:"tty"`
	// Systemd unit or scope name when known.
	Unit OptString `json:"unit"`
	// User identity used to run the exec process.
	User OptSandboxUser `json:"user"`
	// Working directory for the exec process. Defaults to the sandbox's primary source directory. A
	// leading `~` or `~/` is expanded against the run user's home directory inside the sandbox.
	Workdir string `json:"workdir"`
}

